CREATE TABLE docs (
  id        bigserial PRIMARY KEY,
  tenant_id int NOT NULL,
  content   text,
  embedding vector(1536)
);

-- HNSW 索引，使用余弦距离算子类
CREATE INDEX ON docs USING hnsw (embedding vector_cosine_ops);

-- 查询：<=> 为余弦距离，越小越相似
SELECT id, content, 1 - (embedding <=> $1) AS similarity
FROM docs
WHERE tenant_id = 42
ORDER BY embedding <=> $1
LIMIT 5;

