// 假设后端 /api/chat 以 SSE 转发模型输出，每条为 data: {"text": "..."}
const ctrl = new AbortController();
const res = await fetch("/api/chat", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ q: "解释一下 SSE" }),
  signal: ctrl.signal,            // 调用 ctrl.abort() 可中途停止
});

const reader = res.body!.pipeThrough(new TextDecoderStream()).getReader();
let buf = "";
while (true) {
  const { value, done } = await reader.read();
  if (done) break;
  buf += value;
  const events = buf.split("\n\n");   // SSE 事件以空行分隔
  buf = events.pop()!;                // 最后一段可能不完整，留到下次
  for (const ev of events) {
    if (!ev.startsWith("data: ")) continue;
    const payload = ev.slice(6);
    if (payload === "[DONE]") continue;
    output.textContent += JSON.parse(payload).text;
  }
}

import { z } from "zod";

// 一份 schema 同时提供运行时校验和静态类型
const User = z.object({
  id: z.number().int(),
  email: z.string().email(),
  role: z.enum(["admin", "member"]),
});
type User = z.infer<typeof User>;

async function fetchUser(id: number): Promise<User> {
  const res = await fetch(`/api/users/${id}`);
  const data: unknown = await res.json();   // 外部数据先当 unknown
  return User.parse(data);                   // 不符合则抛 ZodError
}

function label(u: User) {
  // role 是联合类型，switch 中会被收窄
  switch (u.role) {
    case "admin": return "管理员";
    case "member": return "成员";
  }
}

# test_pricing.py  运行: pytest -q
import pytest
from unittest.mock import Mock

def final_price(price: float, coupon: str | None, rates) -> float:
    if price < 0:
        raise ValueError("price must be >= 0")
    discount = rates.get(coupon) if coupon else 0
    return round(price * (1 - discount), 2)

@pytest.mark.parametrize("price, coupon, expected", [
    (100, None, 100.0),
    (100, "VIP", 80.0),
    (0, "VIP", 0.0),          # 边界值
])
def test_final_price(price, coupon, expected):
    rates = Mock()
    rates.get.return_value = 0.2   # 替身代替真实折扣服务
    assert final_price(price, coupon, rates) == expected

def test_negative_price_raises():
    with pytest.raises(ValueError):
        final_price(-1, None, Mock())

